<?php defined( 'ABSPATH' ) || exit; $panel_id = isset( $args['panel_id'] ) ? sanitize_html_class( $args['panel_id'] ) : ''; $trigger_id = isset( $args['trigger_id'] ) ? sanitize_html_class( $args['trigger_id'] ) : ''; $items = isset( $args['items'] ) ? (array) $args['items'] : array(); if ( ! $panel_id || ! $trigger_id || ! $items ) return; $is_services = isset( $args['mega_key'] ) && 'services' === $args['mega_key']; ?><div id="<?php echo esc_attr( $panel_id ); ?>" class="nytt01-mega-menu nytt01-mega-menu--featured" aria-labelledby="<?php echo esc_attr( $trigger_id ); ?>" data-menu-dropdown="<?php echo esc_attr( $is_services ? 'services' : 'about' ); ?>" hidden><div class="nytt01-mega-menu__inner"><section class="nytt01-mega-menu__choices"><div class="nytt01-mega-menu__option-list"><?php foreach ( $items as $i => $item ) : ?><button type="button" class="nytt01-mega-option__button" data-rail-item="<?php echo esc_attr( $item['key'] ); ?>" aria-pressed="<?php echo 0 === $i ? 'true' : 'false'; ?>"><?php echo esc_html( $item['title'] ); ?><span aria-hidden="true">→</span></button><?php endforeach; ?></div></section><section class="nytt01-mega-feature" aria-live="polite"><?php foreach ( $items as $i => $item ) : ?><section data-rail-content="<?php echo esc_attr( $item['key'] ); ?>"<?php echo 0 === $i ? '' : ' hidden'; ?> class="nytt01-mega-feature__content"><img src="<?php echo esc_url( $item['image'] ); ?>" alt="" width="720" height="450"><h2><?php echo esc_html( $item['title'] ); ?></h2><p><?php echo esc_html( $item['description'] ); ?></p><ul><?php foreach ( $item['details'] as $detail ) : ?><li><?php echo esc_html( $detail ); ?></li><?php endforeach; ?></ul><a class="btn btn-secondary" href="<?php echo esc_url( $item['url'] ); ?>"><?php esc_html_e( 'Explore service', 'nolan-young-theme-template-01' ); ?></a></section><?php endforeach; ?></section></div></div>
